10a+20\left(\frac{14}{5}\right)=140
\end{equation*}
\begin{equation*}
10a+56=140
\end{equation*}
\begin{equation*}
10a=84
\end{equation*}
\begin{equation*}
a=\frac{84}{10}=\frac{21}{5}
\end{equation*}
